SELECT clock_timestamp() AS db_at,o.id,o.external_order_id,o.wb_order_id,o.status,o.wb_status,o.supplier_status,o.created_at,o.created_at_wb,o.updated_at,o.last_wb_sync_at,p.id AS position_id,p.product_id,p.ozon_sku,p.offer_id,p.quantity,p.reserved_quantity,coalesce((SELECT sum(r.quantity) FROM fbs_order_reservations r WHERE r.fbs_order_id=o.id AND r.tenant_id=o.tenant_id),0) AS legacy_reserved,coalesce((SELECT sum(r.quantity) FROM fbs_order_product_reservations r WHERE r.order_product_id=p.id AND r.tenant_id=o.tenant_id),0) AS position_reserved FROM fbs_orders o JOIN fbs_order_products p ON p.order_id=o.id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon' ORDER BY o.external_order_id LIMIT 80
